-- This source owns its policy facts and projections. MySQL 8.0.
CREATE TABLE IF NOT EXISTS live_policy_snapshot (
 route_id VARCHAR(128) NOT NULL,
 source_date DATE NOT NULL,
 session_hash CHAR(64) CHARACTER SET ascii NOT NULL,
 observed_hour DATETIME NOT NULL,
 session_id TEXT NOT NULL,
 product_id VARCHAR(128) NOT NULL,
 room_id VARCHAR(128) NOT NULL,
 source VARCHAR(16) NOT NULL,
 grain VARCHAR(32) NOT NULL,
 metrics JSON NOT NULL,
 observed_at DATETIME NOT NULL,
 PRIMARY KEY(route_id,source_date,session_hash,observed_hour),
 INDEX idx_snapshot_room (room_id,source_date)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS live_policy_order (
 route_id VARCHAR(128) NOT NULL,
 order_hash CHAR(64) CHARACTER SET ascii NOT NULL,
 order_id TEXT NOT NULL,
 session_id TEXT NOT NULL,
 source_date DATE NOT NULL,
 product_id VARCHAR(128) NOT NULL,
 room_id VARCHAR(128) NOT NULL,
 source VARCHAR(16) NOT NULL,
 payload JSON NOT NULL,
 first_seen_at DATETIME NOT NULL,
 observed_at DATETIME NOT NULL,
 PRIMARY KEY(route_id,order_hash),
 INDEX idx_orders_room (room_id,source_date)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

-- Generated from the owning source module field contract.
-- Raw JSON remains authoritative; missing/invalid/unsupported values are SQL NULL.

-- 【众安保单】统计指标表头字段
CREATE OR REPLACE VIEW v_zhongan_stats AS
SELECT
  route_id,
  product_id,
  room_id,
  source,
  source_date,
  session_id,
  grain,
  observed_at,
  metrics AS raw_metrics,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."_collection"."context"."livePlatform"')) IN ('STRING','INTEGER','DOUBLE','DECIMAL') AND LENGTH(TRIM(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."_collection"."context"."livePlatform"')))) > 0 THEN JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."_collection"."context"."livePlatform"')) ELSE NULL END AS `livePlatform`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."_collection"."context"."dyNo"')) IN ('STRING','INTEGER','DOUBLE','DECIMAL') AND LENGTH(TRIM(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."_collection"."context"."dyNo"')))) > 0 THEN JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."_collection"."context"."dyNo"')) ELSE NULL END AS `dyNo`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."_collection"."context"."anchorNick"')) IN ('STRING','INTEGER','DOUBLE','DECIMAL') AND LENGTH(TRIM(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."_collection"."context"."anchorNick"')))) > 0 THEN JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."_collection"."context"."anchorNick"')) ELSE NULL END AS `anchorNick`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."_collection"."context"."agentLiveName"')) IN ('STRING','INTEGER','DOUBLE','DECIMAL') AND LENGTH(TRIM(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."_collection"."context"."agentLiveName"')))) > 0 THEN JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."_collection"."context"."agentLiveName"')) ELSE NULL END AS `agentLiveName`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."_collection"."context"."startDate"')) IN ('STRING','INTEGER','DOUBLE','DECIMAL') AND LENGTH(TRIM(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."_collection"."context"."startDate"')))) > 0 THEN JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."_collection"."context"."startDate"')) ELSE NULL END AS `startDate`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."_collection"."context"."roomId"')) IN ('STRING','INTEGER','DOUBLE','DECIMAL') AND LENGTH(TRIM(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."_collection"."context"."roomId"')))) > 0 THEN JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."_collection"."context"."roomId"')) ELSE NULL END AS `roomId`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."_collection"."context"."startTime"')) IN ('STRING','INTEGER','DOUBLE','DECIMAL') AND LENGTH(TRIM(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."_collection"."context"."startTime"')))) > 0 THEN JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."_collection"."context"."startTime"')) ELSE NULL END AS `startTime`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."_collection"."context"."collectedAt"')) IN ('STRING','INTEGER','DOUBLE','DECIMAL') AND LENGTH(TRIM(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."_collection"."context"."collectedAt"')))) > 0 THEN JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."_collection"."context"."collectedAt"')) ELSE NULL END AS `collectedAt`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."cost"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."cost"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."cost"')) AS DECIMAL(65,30)) ELSE NULL END AS `cost`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."policyCnt"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."policyCnt"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."policyCnt"')) AS DECIMAL(65,30)) ELSE NULL END AS `policyCnt`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."orderCnt"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."orderCnt"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."orderCnt"')) AS DECIMAL(65,30)) ELSE NULL END AS `orderCnt`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."distinctOrder"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."distinctOrder"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."distinctOrder"')) AS DECIMAL(65,30)) ELSE NULL END AS `distinctOrder`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."policyRate"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."policyRate"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."policyRate"')) AS DECIMAL(65,30)) ELSE NULL END AS `policyRate`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."annualPremiumRate"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."annualPremiumRate"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."annualPremiumRate"')) AS DECIMAL(65,30)) ELSE NULL END AS `annualPremiumRate`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."multipleRate"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."multipleRate"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."multipleRate"')) AS DECIMAL(65,30)) ELSE NULL END AS `multipleRate`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."totalPremium"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."totalPremium"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."totalPremium"')) AS DECIMAL(65,30)) ELSE NULL END AS `totalPremium`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."totalAmount"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."totalAmount"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."totalAmount"')) AS DECIMAL(65,30)) ELSE NULL END AS `totalAmount`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."liveLandingUV"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."liveLandingUV"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."liveLandingUV"')) AS DECIMAL(65,30)) ELSE NULL END AS `liveLandingUV`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."roi"')) = 'NULL' THEN NULL ELSE JSON_EXTRACT(metrics, '$."roi"') END AS `roi`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."policyCost"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."policyCost"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."policyCost"')) AS DECIMAL(65,30)) ELSE NULL END AS `policyCost`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."premiumAvg"')) = 'NULL' THEN NULL ELSE JSON_EXTRACT(metrics, '$."premiumAvg"') END AS `premiumAvg`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."emptyCostRate"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."emptyCostRate"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."emptyCostRate"')) AS DECIMAL(65,30)) ELSE NULL END AS `emptyCostRate`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."roomCreateTime"')) IN ('STRING','INTEGER','DOUBLE','DECIMAL') AND LENGTH(TRIM(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."roomCreateTime"')))) > 0 THEN JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."roomCreateTime"')) ELSE NULL END AS `roomCreateTime`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."roomFinishTime"')) IN ('STRING','INTEGER','DOUBLE','DECIMAL') AND LENGTH(TRIM(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."roomFinishTime"')))) > 0 THEN JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."roomFinishTime"')) ELSE NULL END AS `roomFinishTime`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."mayAmount"')) = 'NULL' THEN NULL ELSE JSON_EXTRACT(metrics, '$."mayAmount"') END AS `mayAmount`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."adLiveEstimatedRoi"')) = 'NULL' THEN NULL ELSE JSON_EXTRACT(metrics, '$."adLiveEstimatedRoi"') END AS `adLiveEstimatedRoi`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."adInfoList"')) = 'NULL' THEN NULL ELSE JSON_EXTRACT(metrics, '$."adInfoList"') END AS `adInfoList`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."otp"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."otp"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."otp"')) AS DECIMAL(65,30)) ELSE NULL END AS `otp`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."mainRoi"')) = 'NULL' THEN NULL ELSE JSON_EXTRACT(metrics, '$."mainRoi"') END AS `mainRoi`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."notMainRoi"')) = 'NULL' THEN NULL ELSE JSON_EXTRACT(metrics, '$."notMainRoi"') END AS `notMainRoi`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."lumpSumPaymentRate"')) = 'NULL' THEN NULL ELSE JSON_EXTRACT(metrics, '$."lumpSumPaymentRate"') END AS `lumpSumPaymentRate`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."lumpSumPaidRate"')) = 'NULL' THEN NULL ELSE JSON_EXTRACT(metrics, '$."lumpSumPaidRate"') END AS `lumpSumPaidRate`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."wlPaidRate"')) = 'NULL' THEN NULL ELSE JSON_EXTRACT(metrics, '$."wlPaidRate"') END AS `wlPaidRate`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."packageRate"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."packageRate"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."packageRate"')) AS DECIMAL(65,30)) ELSE NULL END AS `packageRate`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."adLiveFunnelPlot"')) = 'NULL' THEN NULL ELSE JSON_EXTRACT(metrics, '$."adLiveFunnelPlot"') END AS `adLiveFunnelPlot`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."showCnt"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."showCnt"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."showCnt"')) AS DECIMAL(65,30)) ELSE NULL END AS `showCnt`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."liveWatchCount"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."liveWatchCount"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."liveWatchCount"')) AS DECIMAL(65,30)) ELSE NULL END AS `liveWatchCount`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."liveCardIconComponentClickCount"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."liveCardIconComponentClickCount"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."liveCardIconComponentClickCount"')) AS DECIMAL(65,30)) ELSE NULL END AS `liveCardIconComponentClickCount`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."upgradeRate"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."upgradeRate"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."upgradeRate"')) AS DECIMAL(65,30)) ELSE NULL END AS `upgradeRate`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."cancelZeroCnt"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."cancelZeroCnt"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."cancelZeroCnt"')) AS DECIMAL(65,30)) ELSE NULL END AS `cancelZeroCnt`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."cancelZeroRate"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."cancelZeroRate"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."cancelZeroRate"')) AS DECIMAL(65,30)) ELSE NULL END AS `cancelZeroRate`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."firstYearRecyclingMain"')) = 'NULL' THEN NULL ELSE JSON_EXTRACT(metrics, '$."firstYearRecyclingMain"') END AS `firstYearRecyclingMain`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."uvValue"')) = 'NULL' THEN NULL ELSE JSON_EXTRACT(metrics, '$."uvValue"') END AS `uvValue`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."averageOrderValue"')) = 'NULL' THEN NULL ELSE JSON_EXTRACT(metrics, '$."averageOrderValue"') END AS `averageOrderValue`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."averageInsuranceNum"')) = 'NULL' THEN NULL ELSE JSON_EXTRACT(metrics, '$."averageInsuranceNum"') END AS `averageInsuranceNum`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."sixtyPolicyPercentage"')) = 'NULL' THEN NULL ELSE JSON_EXTRACT(metrics, '$."sixtyPolicyPercentage"') END AS `sixtyPolicyPercentage`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."timeSharingConsumption"')) = 'NULL' THEN NULL ELSE JSON_EXTRACT(metrics, '$."timeSharingConsumption"') END AS `timeSharingConsumption`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."inboundCnt"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."inboundCnt"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."inboundCnt"')) AS DECIMAL(65,30)) ELSE NULL END AS `inboundCnt`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(metrics, '$."inboundSpeakRate"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."inboundSpeakRate"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(metrics, '$."inboundSpeakRate"')) AS DECIMAL(65,30)) ELSE NULL END AS `inboundSpeakRate`
FROM live_policy_snapshot WHERE source = 'zhongan';

-- 【众安保单】订单表头字段
CREATE OR REPLACE VIEW v_zhongan_orders AS
SELECT
  route_id,
  product_id,
  room_id,
  source,
  source_date,
  session_id,
  first_seen_at,
  observed_at,
  payload AS raw_payload,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(payload, '$."_collection"."context"."livePlatform"')) IN ('STRING','INTEGER','DOUBLE','DECIMAL') AND LENGTH(TRIM(JSON_UNQUOTE(JSON_EXTRACT(payload, '$."_collection"."context"."livePlatform"')))) > 0 THEN JSON_UNQUOTE(JSON_EXTRACT(payload, '$."_collection"."context"."livePlatform"')) ELSE NULL END AS `livePlatform`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(payload, '$."_collection"."context"."dyNo"')) IN ('STRING','INTEGER','DOUBLE','DECIMAL') AND LENGTH(TRIM(JSON_UNQUOTE(JSON_EXTRACT(payload, '$."_collection"."context"."dyNo"')))) > 0 THEN JSON_UNQUOTE(JSON_EXTRACT(payload, '$."_collection"."context"."dyNo"')) ELSE NULL END AS `dyNo`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(payload, '$."_collection"."context"."anchorNick"')) IN ('STRING','INTEGER','DOUBLE','DECIMAL') AND LENGTH(TRIM(JSON_UNQUOTE(JSON_EXTRACT(payload, '$."_collection"."context"."anchorNick"')))) > 0 THEN JSON_UNQUOTE(JSON_EXTRACT(payload, '$."_collection"."context"."anchorNick"')) ELSE NULL END AS `anchorNick`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(payload, '$."_collection"."context"."agentLiveName"')) IN ('STRING','INTEGER','DOUBLE','DECIMAL') AND LENGTH(TRIM(JSON_UNQUOTE(JSON_EXTRACT(payload, '$."_collection"."context"."agentLiveName"')))) > 0 THEN JSON_UNQUOTE(JSON_EXTRACT(payload, '$."_collection"."context"."agentLiveName"')) ELSE NULL END AS `agentLiveName`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(payload, '$."_collection"."context"."startDate"')) IN ('STRING','INTEGER','DOUBLE','DECIMAL') AND LENGTH(TRIM(JSON_UNQUOTE(JSON_EXTRACT(payload, '$."_collection"."context"."startDate"')))) > 0 THEN JSON_UNQUOTE(JSON_EXTRACT(payload, '$."_collection"."context"."startDate"')) ELSE NULL END AS `startDate`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(payload, '$."_collection"."context"."roomId"')) IN ('STRING','INTEGER','DOUBLE','DECIMAL') AND LENGTH(TRIM(JSON_UNQUOTE(JSON_EXTRACT(payload, '$."_collection"."context"."roomId"')))) > 0 THEN JSON_UNQUOTE(JSON_EXTRACT(payload, '$."_collection"."context"."roomId"')) ELSE NULL END AS `roomId`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(payload, '$."_collection"."context"."startTime"')) IN ('STRING','INTEGER','DOUBLE','DECIMAL') AND LENGTH(TRIM(JSON_UNQUOTE(JSON_EXTRACT(payload, '$."_collection"."context"."startTime"')))) > 0 THEN JSON_UNQUOTE(JSON_EXTRACT(payload, '$."_collection"."context"."startTime"')) ELSE NULL END AS `startTime`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(payload, '$."_collection"."context"."collectedAt"')) IN ('STRING','INTEGER','DOUBLE','DECIMAL') AND LENGTH(TRIM(JSON_UNQUOTE(JSON_EXTRACT(payload, '$."_collection"."context"."collectedAt"')))) > 0 THEN JSON_UNQUOTE(JSON_EXTRACT(payload, '$."_collection"."context"."collectedAt"')) ELSE NULL END AS `collectedAt`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(payload, '$."orderNo"')) IN ('STRING','INTEGER','DOUBLE','DECIMAL') AND LENGTH(TRIM(JSON_UNQUOTE(JSON_EXTRACT(payload, '$."orderNo"')))) > 0 THEN JSON_UNQUOTE(JSON_EXTRACT(payload, '$."orderNo"')) ELSE NULL END AS `orderNo`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(payload, '$."productName"')) IN ('STRING','INTEGER','DOUBLE','DECIMAL') AND LENGTH(TRIM(JSON_UNQUOTE(JSON_EXTRACT(payload, '$."productName"')))) > 0 THEN JSON_UNQUOTE(JSON_EXTRACT(payload, '$."productName"')) ELSE NULL END AS `productName`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(payload, '$."bizDate"')) IN ('STRING','INTEGER','DOUBLE','DECIMAL') AND LENGTH(TRIM(JSON_UNQUOTE(JSON_EXTRACT(payload, '$."bizDate"')))) > 0 THEN JSON_UNQUOTE(JSON_EXTRACT(payload, '$."bizDate"')) ELSE NULL END AS `bizDate`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(payload, '$."bizTime"')) IN ('STRING','INTEGER','DOUBLE','DECIMAL') AND LENGTH(TRIM(JSON_UNQUOTE(JSON_EXTRACT(payload, '$."bizTime"')))) > 0 THEN JSON_UNQUOTE(JSON_EXTRACT(payload, '$."bizTime"')) ELSE NULL END AS `bizTime`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(payload, '$."orderAmount"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(payload, '$."orderAmount"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(payload, '$."orderAmount"')) AS DECIMAL(65,30)) ELSE NULL END AS `orderAmount`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(payload, '$."orderStatus"')) IN ('STRING','INTEGER','DOUBLE','DECIMAL') AND LENGTH(TRIM(JSON_UNQUOTE(JSON_EXTRACT(payload, '$."orderStatus"')))) > 0 THEN JSON_UNQUOTE(JSON_EXTRACT(payload, '$."orderStatus"')) ELSE NULL END AS `orderStatus`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(payload, '$."holderInfo"."name"')) IN ('STRING','INTEGER','DOUBLE','DECIMAL') AND LENGTH(TRIM(JSON_UNQUOTE(JSON_EXTRACT(payload, '$."holderInfo"."name"')))) > 0 THEN JSON_UNQUOTE(JSON_EXTRACT(payload, '$."holderInfo"."name"')) ELSE NULL END AS `holderInfo.name`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(payload, '$."holderInfo"."age"')) IN ('STRING','INTEGER','DOUBLE','DECIMAL') AND LENGTH(TRIM(JSON_UNQUOTE(JSON_EXTRACT(payload, '$."holderInfo"."age"')))) > 0 THEN JSON_UNQUOTE(JSON_EXTRACT(payload, '$."holderInfo"."age"')) ELSE NULL END AS `holderInfo.age`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(payload, '$."payMethod"')) IN ('STRING','INTEGER','DOUBLE','DECIMAL') AND LENGTH(TRIM(JSON_UNQUOTE(JSON_EXTRACT(payload, '$."payMethod"')))) > 0 THEN JSON_UNQUOTE(JSON_EXTRACT(payload, '$."payMethod"')) ELSE NULL END AS `payMethod`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(payload, '$."holderInfo"."hasSi"')) = 'NULL' THEN NULL ELSE JSON_EXTRACT(payload, '$."holderInfo"."hasSi"') END AS `holderInfo.hasSi`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(payload, '$."holderInfo"."relation"')) = 'NULL' THEN NULL ELSE JSON_EXTRACT(payload, '$."holderInfo"."relation"') END AS `holderInfo.relation`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(payload, '$."holderInfo"."uwStatus"')) = 'NULL' THEN NULL ELSE JSON_EXTRACT(payload, '$."holderInfo"."uwStatus"') END AS `holderInfo.uwStatus`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(payload, '$."insuredInfoList"')) = 'NULL' THEN NULL ELSE JSON_EXTRACT(payload, '$."insuredInfoList"') END AS `insuredInfoList`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(payload, '$."paymentMethod"')) = 'NULL' THEN NULL ELSE JSON_EXTRACT(payload, '$."paymentMethod"') END AS `paymentMethod`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(payload, '$."orderCnt"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(payload, '$."orderCnt"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(payload, '$."orderCnt"')) AS DECIMAL(65,30)) ELSE NULL END AS `orderCnt`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(payload, '$."paidCnt"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(payload, '$."paidCnt"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(payload, '$."paidCnt"')) AS DECIMAL(65,30)) ELSE NULL END AS `paidCnt`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(payload, '$."upgradeFlag"')) IN ('STRING','INTEGER','DOUBLE','DECIMAL') AND LENGTH(TRIM(JSON_UNQUOTE(JSON_EXTRACT(payload, '$."upgradeFlag"')))) > 0 THEN JSON_UNQUOTE(JSON_EXTRACT(payload, '$."upgradeFlag"')) ELSE NULL END AS `upgradeFlag`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(payload, '$."accountId"')) = 'NULL' THEN NULL ELSE JSON_EXTRACT(payload, '$."accountId"') END AS `accountId`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(payload, '$."nextPage"')) IN ('INTEGER','DOUBLE','DECIMAL','STRING') AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(payload, '$."nextPage"')), '^[+-]?[0-9]{1,35}([.][0-9]{1,30})?$', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(payload, '$."nextPage"')) AS DECIMAL(65,30)) ELSE NULL END AS `nextPage`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(payload, '$."orderDetailList"')) = 'NULL' THEN NULL ELSE JSON_EXTRACT(payload, '$."orderDetailList"') END AS `orderDetailList`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(payload, '$."moreDetailFlag"')) IN ('STRING','INTEGER','DOUBLE','DECIMAL') AND LENGTH(TRIM(JSON_UNQUOTE(JSON_EXTRACT(payload, '$."moreDetailFlag"')))) > 0 THEN JSON_UNQUOTE(JSON_EXTRACT(payload, '$."moreDetailFlag"')) ELSE NULL END AS `moreDetailFlag`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(payload, '$."media"')) = 'NULL' THEN NULL ELSE JSON_EXTRACT(payload, '$."media"') END AS `media`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(payload, '$."payBlockInfo"')) = 'NULL' THEN NULL ELSE JSON_EXTRACT(payload, '$."payBlockInfo"') END AS `payBlockInfo`,
  CASE WHEN JSON_TYPE(JSON_EXTRACT(payload, '$."hasSendReachSms"')) = 'NULL' THEN NULL ELSE JSON_EXTRACT(payload, '$."hasSendReachSms"') END AS `hasSendReachSms`
FROM live_policy_order WHERE source = 'zhongan';

